function standby = mfun_imfvc_standby(enable, p)
%MFUN_IMFVC_STANDBY Block standby of the control system.
%   Generated by motulator_export from the MATLAB port of motulator; the MATLAB Function
%   block of a model calls this function, copied into the folder of the model. The
%   parameters are the fields of the struct p, the struct of the block in the struct
%   ctrl_par of the parameters of the blocks of its control system (e.g.,
%   ctrl_par.SpeedController, see the function of the parameters of the control system,
%   e.g., fvc_params; [] as NaN). The state is in persistent variables, of which each
%   MATLAB Function block has its own copy.
persistent self
if isempty(self)
    self = struct('release_step', false);
end
% Standby while the gates are blocked and at the first sampling instant
% after the release of a sensorless drive
standby = double(enable <= 0 || self.release_step);
self.release_step = p.sensorless > 0 && enable <= 0;
end
